INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-000059', '2', 65, NULL, '435147', E'あさぎり町内在住の65歳以上の方\n令和6年4月1日以降に運転免許証を自主返納し、返納から1年以内の方\n運転免許証の失効は対象外\n「ほのぼの号」の利用登録が必要', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
