INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-000062', '2', 65, NULL, NULL, E'運転免許を自主返納した65歳以上の方\nきっぷの購入時に「運転経歴証明書」の提示が必要', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
