INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-001046', '2', NULL, NULL, NULL, E'(1)(3)は年齢制限なし、(2)は65歳以上または障がい者の方のみ\n契約者の運転経歴証明書の提示が必要', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-001047', '2', NULL, NULL, NULL, E'運転免許を自主返納したご本人及びご家族\n契約者の「運転経歴証明書」または交付済シール付きマイナンバーカードの提示が必要\n必ず「運転免許自主返納サービス利用」と伝えてください', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-001048', '2', NULL, NULL, NULL, E'ご本人及びその家族（年齢制限なし）\n「申請による運転免許の取消通知書」または「運転経歴証明書」の提示が必要\n申込時にコールセンターのオペレーターへ優待利用の旨を申告していただくか、見積もりまでにサービススタッフへ申し出てください\n※他割引との併用不可', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO BENEFIT_ELIGIBILITY (BENEFIT_ID, LICENSE_STATUS, MIN_AGE, MAX_AGE, MUNICIPALITY_CD, NOTE, SYS_CREATED_AT, SYS_UPDATED_AT) VALUES ('BEN-001049', '2', NULL, NULL, NULL, E'ご本人のみ\n「申請による運転免許の取消通知書」または「運転経歴証明書」の提示が必要\n※県内の提携業者が対応', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
